const API = new URL('./api/',location.href.split('#')[0]).pathname;
const $ = s=>document.querySelector(s);
const esc = x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'m3 10 9-7 9 7v11h-6v-7H9v7H3V10',user:'M20 21v-3a5 5 0 0 0-5-5H9a5 5 0 0 0-5 5v3m12-15a4 4 0 1 1-8 0 4 4 0 0 1 8 0',paddle:'M14 14l6 6m-7-5a7 7 0 1 1 2-2l-2 2M18 3h.01',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-17a4 4 0 0 1 0 8m6 9v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',trophy:'M8 21h8m-4-4v4M8 3h8v7a4 4 0 0 1-8 0V3m0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4',activity:'M2 12h4l3-8 6 16 3-8h4',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3V5m0 1 9 7 9-7',shield:'m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4m-4 9 3 3 5-6',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3',logout:'M9 4H4v16h5m5-16 7 8-7 8m-5-8h12',search:'M21 21l-6-6m2-5a7 7 0 1 1-14 0 7 7 0 0 1 14 0',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3V4m9 2v15'};
const icon = name=>name==='paddle'?`<svg viewBox="0 0 24 24" aria-hidden="true"><g transform="rotate(-35 11 11)"><rect x="8.5" y="14" width="5" height="9" rx="1.5" fill="currentColor"/><ellipse cx="11" cy="9" rx="8" ry="9" fill="currentColor"/><path d="M4 11h14" stroke="white" stroke-opacity=".7" stroke-width="1.2"/></g><circle cx="20" cy="3" r="2.2" fill="currentColor"/></svg>`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.paddle}"/></svg>`;
const avatar=(p,big=false)=>p?.avatar_version?`<img class="avatar photo ${big?'big':''}" src="${API}avatars/${p.id}/${esc(p.avatar_version)}.jpg" alt="${esc(p.name)}的头像" loading="lazy" width="${big?68:38}" height="${big?68:38}">`:`<span class="avatar ${big?'big ':''}c${(p?.id||0)%4}" aria-hidden="true">${esc((p?.name||'?').slice(-2))}</span>`;
const num=x=>Number(x||0).toLocaleString('en-US');
const when=(x,full=false)=>x?new Date(x).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',...(full?{year:'numeric'}:{})}):'待定';
const day=x=>new Date(x).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const best=x=>({3:'三局两胜',5:'五局三胜',7:'七局四胜'}[x]);
const statuses={invited:['待接受','orange'],accepted:['已约定','blue'],reported:['待确认赛果','orange'],completed:['已确认',''],declined:['已婉拒','muted'],cancelled:['已取消','muted'],voided:['已作废','muted']};
let state={user:null,csrf:null,players:[],matches:[],mine:[],stats:{members:0,matches:0},mail_ready:false,admin:null},tab='all',filter='',currentProfile=null,loadSequence=0;
let toastTimer,pendingAvatar='';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
async function api(path,data){const res=await fetch(API+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''}:{},body:data?JSON.stringify(data):undefined});let result;try{result=await res.json()}catch{throw Error('服务暂不可用，请稍后重试')}if(!res.ok)throw Error(result.error||'请求失败');return result}
async function refresh(){const [boot,players,matches,analytics,dm,ev]=await Promise.all([api('bootstrap'),api('players'),api('matches'),api('analytics'),api('doubles'),api('events')]);if(state.user?.id!==boot.user?.id)tab=boot.user?'mine':'all';Object.assign(state,boot,{players:players.players,matches:matches.matches,analytics,doubles:dm.doubles,events:ev.events});document.title=(state.club?.name||'OpenChinaTT')+' · 约一场好球'}

const route=()=>location.hash.slice(1)||'home';
const link=(text,to,ic='arrow')=>`<a class="link" href="#${to}">${text}${icon(ic)}</a>`;
const empty=(title,desc,action='invite',button='发起第一场对战',ic='paddle')=>`<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${desc}</p>${action?`<button class="btn small outline" data-action="${action}">${button}${icon('arrow')}</button>`:''}</div>`;
function head(title,desc,eye='THE CLUB, YOUR COURT',cta=true){return `<div class="page-head"><div><div class="eyebrow"><span class="dot"></span>${eye}</div><h1>${title}</h1><p>${desc}</p></div>${cta?`<button class="btn" data-action="invite">${icon('plus')}发起对战</button>`:''}</div>`}
function shell(content){const r=route().split('/')[0],u=state.user,pendingCount=state.mine.filter(m=>(m.status==='invited'&&m.b_id===u?.id)||(m.status==='reported'&&m.reporter_id!==u?.id)).length+(state.mine_doubles||[]).filter(doubleNeedsReply).length;$('#app').innerHTML=`<header><a href="#home" class="brand"><img class="brand-logo" src="./logo.svg" alt="学院盾徽与乒乓球拍标志" width="44" height="44"><span><strong>${esc(state.club?.name||'校园乒乓')}</strong><small>${esc(state.club?.english_name||'OPENCHINATT')}</small></span></a><nav aria-label="主导航">${[['home','俱乐部'],['rankings','积分榜'],['matches','对战中心'],['players','球友'],['events','赛事'],['rules','积分规则']].map(([key,label])=>`<a href="#${key}" class="${r===key?'active':''}" ${r===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="header-actions"><a class="mobile-players" href="#players" aria-label="查找球友">${icon('users')}</a>${u?`<a href="#me" class="user-pill" aria-label="我的账号 ${esc(u.name)}">${avatar(u)}<span class="user-label">${esc(u.name)}</span></a>${u.role==='admin'?`<a href="#admin" class="btn ghost small" aria-label="管理后台">${icon('shield')}</a>`:''}`:`<button class="btn ghost" data-action="login">登录</button><button class="btn" data-action="register">加入俱乐部${icon('arrow')}</button>`}</div></header><main class="container fade-in">${content}</main><div class="mobile-nav" role="navigation" aria-label="手机快捷导航">${[['home','首页','home'],['rankings','积分榜','trophy']].map(([key,label,ic])=>`<a href="#${key}" class="${r===key?'active':''}">${icon(ic)}<span>${label}</span></a>`).join('')}<button class="mobile-invite" data-action="invite"><span>${icon('plus')}</span><small>约一场</small></button>${[['matches','对战','paddle'],['me','我的','user']].map(([key,label,ic])=>`<a href="#${key}" class="${r===key?'active':''}">${icon(ic)}<span>${label}${key==='matches'&&pendingCount?`<b class="nav-count">${pendingCount}</b>`:''}</span></a>`).join('')}</div><footer><span>${esc(state.club?.full_name||'校园')} · 乒乓球社区 <span aria-hidden="true">/</span> MAKE EVERY POINT COUNT.</span><div><a href="#rules">校内独立积分 · 参考 ChinaTT</a> &nbsp; · &nbsp; <a href="#rules/privacy">隐私与使用说明</a></div></footer>`}
const art=`<svg class="hero-art" viewBox="0 0 380 300" aria-hidden="true"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#bbd7b2" stroke-opacity=".16"/></pattern><linearGradient id="table" x2="1" y2="1"><stop stop-color="#337662"/><stop offset="1" stop-color="#225d4c"/></linearGradient></defs><ellipse cx="230" cy="248" rx="138" ry="18" fill="#082c25" opacity=".35"/><path d="M88 145 254 68 375 157 207 247Z" fill="#0d342c"/><path d="m88 137 166-77 121 89-168 90Z" fill="url(#table)" stroke="#9bbca2" stroke-width="2"/><path d="m99 139 154-71 110 80-155 83Z" fill="none" stroke="#c3d5b1" stroke-width="1.5"/><path d="m174 99 121 88M150 178l155-74" stroke="#cfddc0" stroke-width="1.5"/><path d="m146 181 3-43 157-73v43Z" fill="url(#grid)" stroke="#d4debd" stroke-width="1.4"/><path d="m149 138 157-73" stroke="#f2f1d4" stroke-width="4"/><path d="M148 138v48m158-121v47" stroke="#b7d18d" stroke-width="4"/><path d="m126 173-2 65m171-31v47" stroke="#819a7b" stroke-width="7"/><g transform="rotate(30 264 188)"><rect x="258" y="218" width="13" height="43" rx="5" fill="#d7bb8b"/><ellipse cx="265" cy="198" rx="31" ry="38" fill="#d9ed86"/><ellipse cx="265" cy="195" rx="29" ry="35" fill="#e2f197"/><path d="M240 177c9-13 25-16 36-8" fill="none" stroke="#ecf5c1" stroke-width="2"/></g><g class="ball"><circle cx="221" cy="69" r="12" fill="#fbf9e4"/><path d="m216 65 4-3" stroke="white" stroke-width="2" stroke-linecap="round"/></g><path d="m206 40-5-12m-12 27-12-5m43-20 3-12" stroke="#bfd287" stroke-width="2" stroke-linecap="round"/><text x="112" y="279" fill="#89ad98" font-size="8" letter-spacing="4" font-family="sans-serif">GOOD GAMES. GREAT PEOPLE.</text></svg>`;
function sparkline(logs=[],large=false){const vals=[logs[0]?.before_rating??1500,...logs.map(x=>x.after_rating)];const lo=Math.min(...vals)-15,hi=Math.max(...vals)+15;const points=vals.length>1?vals.map((v,i)=>`${10+i*280/(vals.length-1)},${110-(v-lo)/(hi-lo)*90}`).join(' '):'10,65 290,65';return `<svg class="${large?'':'sparkline'}" viewBox="0 0 300 130" preserveAspectRatio="none" role="img" aria-label="${vals.length>1?'积分变化趋势':'初始积分1500，暂无变化'}"><path d="M10 110H290M10 65H290M10 20H290" stroke="#e9eee3" stroke-width="1" stroke-dasharray="4 5"/><polyline points="${points}" stroke="#96ac61" fill="none" stroke-width="2.5" vector-effect="non-scaling-stroke"/><circle cx="290" cy="${points.split(' ').at(-1).split(',')[1]}" r="4" fill="#96ac61"/></svg>`}
function leaderboard(players,compact=false){return `<div class="table-wrap"><table class="leaderboard"><thead><tr><th>排名</th><th>球友</th><th>积分</th><th>胜率 / 场次</th>${compact?'':'<th></th>'}</tr></thead><tbody>${players.map(p=>{const i=state.players.findIndex(x=>x.id===p.id);return `<tr><td><span class="rank ${i<3?'top':''}">${rankBadge(i)}</span></td><td><a href="#player/${p.id}" class="player-name">${avatar(p)}<span>${esc(p.name)}${p.id===state.user?.id?' <span class="badge">我</span>':''}<small>${p.title?'称号 · '+esc(p.title):p.role==='admin'?'俱乐部管理员':`${esc(p.grip)} · ${esc(p.hand)}`}</small></span></a></td><td><strong class="score">${num(p.rating)}</strong></td><td>${p.played?Math.round(p.wins/p.played*100)+'%':'—'} <span class="hint">/ ${p.played} 场</span></td>${compact?'':`<td><button class="btn outline small" data-action="invite" data-id="${p.id}">${p.id===state.user?.id?'我的对战':'约一场'}${icon('arrow')}</button></td>`}</tr>`}).join('')}</tbody></table></div>${!players.length?empty('还没有匹配的球友','换个昵称试试吧。',null):''}`}
function mini(m){return `<div class="match-mini"><div class="vs-row"><a class="side" href="#player/${m.a_id}">${avatar({id:m.a_id,name:m.a_name,avatar_version:m.a_avatar_version})}${esc(m.a_name)}</a><span class="vs-score">${m.score_a} : ${m.score_b}</span><a class="side" href="#player/${m.b_id}">${esc(m.b_name)}${avatar({id:m.b_id,name:m.b_name,avatar_version:m.b_avatar_version})}</a></div><div class="meta"><span>${day(m.confirmed_at)}</span><span>${esc(m.venue)}</span><span class="badge">双方已确认</span></div></div>`}
function home(){const u=state.user;const my=state.players.find(p=>p.id===u?.id);const rank=my?state.players.indexOf(my)+1:null;const pending=state.mine.filter(m=>m.status==='invited'&&m.b_id===u?.id||m.status==='reported'&&m.reporter_id!==u?.id).length+(state.mine_doubles||[]).filter(doubleNeedsReply).length;const recent=state.matches.filter(m=>m.status==='completed').slice(0,3);const logs=state.mine.filter(m=>m.status==='completed'&&m.settled_at).sort((a,b)=>a.confirmed_at.localeCompare(b.confirmed_at)||a.id-b.id).map(m=>({before_rating:m.a_id===u?.id?m.a_before:m.b_before,after_rating:m.a_id===u?.id?m.a_before+m.a_delta:m.b_before+m.b_delta}));return `${head(u?`${esc(u.name)}，今天来一局？`:'好球友，在这里相遇。','一张球台，一群同频的人。让每一次挥拍，都留下进步的轨迹。','WELCOME TO YOUR CLUB',false)}<div class="hero-grid ${u?'member-home':''}"><section class="hero"><div class="eyebrow"><span class="dot"></span>YOUR NEXT GREAT RALLY STARTS HERE</div><h2>约一场好球，<br>把热爱<em>打出来。</em></h2><p>从 1500 分一起出发。找到对手、切磋球技，<br>在每一回合里，遇见更好的自己。</p><button class="btn lime" data-action="invite">${icon('plus')}发起一场对战${icon('arrow')}</button>${art}</section><section class="rating-card"><div class="rating-top"><span>${u?'我的俱乐部积分':'你的乒乓新起点'}</span><span class="badge">${u?'CLUB RATING':'统一初始积分'}</span></div><div class="rating-value">${num(u?.rating??1500)}<small>PTS</small></div><p class="rating-desc">${u?`已完成 ${my?.played||0} 场对战 · ${my?.played?'继续保持热爱':'期待你的第一场'}`:'每一位新球友，站上同一条起跑线'}</p>${sparkline(logs)}<div class="rating-bottom"><span>${rank?'俱乐部排名 #'+rank:'向下一次突破出发'}</span>${link(u?'个人主页':'了解积分规则',u?'me':'rules','chevron')}</div></section></div><div class="stats"><div class="stat"><span class="stat-icon">${icon('users')}</span><div><div class="stat-number">${num(state.stats.members)}<small>位</small></div><div class="stat-title">一起热爱乒乓的球友</div></div></div><div class="stat"><span class="stat-icon">${icon('paddle')}</span><div><div class="stat-number">${num(state.stats.matches)}<small>场</small></div><div class="stat-title">已确认的精彩对战</div></div></div><div class="stat"><span class="stat-icon">${icon(u?'calendar':'shield')}</span><div><div class="stat-number">${u?pending:'双方'}<small>${u?'条待办':'确认'}</small></div><div class="stat-title">${u?'邀请与赛果等待你的回应':'单打积分每日00:00结算'}</div></div></div></div><div class="two-col"><section class="panel"><div class="panel-title"><div><h2>${icon('trophy')}俱乐部积分榜</h2><p>每一次进步，都值得被看见</p></div>${link('完整榜单','rankings')}</div>${leaderboard(state.players.slice(0,5),true)}<div class="table-note">全员初始 1500 分 · 同分按加入顺序展示 · 北京时间每天00:00统一结算</div></section><div><section class="panel"><div class="panel-title"><div><h2>${icon('activity')}最近的好球</h2><p>在这里，胜负之外还有友谊</p></div>${link('全部','matches')}</div>${recent.length?`<div class="feed">${recent.map(mini).join('')}</div>`:empty('下一场精彩，等你开球','俱乐部还没有已确认的对战。<br>约上球友，留下第一场记录。')}</section><div class="new-here"><h3>你的球拍，也有自己的故事。</h3><p>记录底板、正反手胶皮和打法，<br>让球友在开打之前，先认识你。</p><button class="link" data-action="equipment">完善我的装备${icon('arrow')}</button></div></div></div><div class="steps"><div class="step"><span class="num">01</span><div><strong>加入，找到同频球友</strong><p>注册你的账号，以 1500 分开启旅程。</p></div></div><div class="step"><span class="num">02</span><div><strong>约球，让双方都点头</strong><p>自由发起邀请，共同确认时间与地点。</p></div></div><div class="step"><span class="num">03</span><div><strong>开打，让进步有迹可循</strong><p>提交赛果，对方确认后，积分于每日00:00结算。</p></div></div></div>`}
function rankings(){const list=state.players.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase()));return `${head('每一分，都是实力。','一起向上，也享受每一场势均力敌。','THE CLUB LEADERBOARD')}<div class="filters"><label class="sr-only" for="search">搜索球友</label><input id="search" placeholder="搜索球友昵称…" type="search" value="${esc(filter)}"><span class="hint">共 ${state.players.length} 位球友 · 积分每日00:00更新</span></div><section class="panel">${leaderboard(list)}<div class="table-note">按积分降序展示；同分按注册顺序展示。未参赛用户仍以 1500 分上榜。</div></section>`}
function players(){const list=state.players.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase()));return `${head('一拍即合的球友。','认识新的对手，也认识新的朋友。','MEET YOUR NEXT RALLY PARTNER')}<div class="filters"><label class="sr-only" for="search">搜索球友</label><input id="search" placeholder="搜索球友昵称…" type="search" value="${esc(filter)}"><span class="hint">${state.players.length} 位球友，在这里等你</span></div><div class="grid-3">${list.map(p=>`<a href="#player/${p.id}" class="panel player-card"><div class="player-card-head">${avatar(p)}<div><h3>${esc(p.name)}</h3>${titleBadge(p)}<div class="meta">${esc(p.grip)} · ${esc(p.hand)}${p.role==='admin'?' · 管理员':''}</div></div><span class="score">${num(p.rating)}</span></div><div class="equipment">底板 · ${esc(p.blade||'还未填写')}<br>正手 · ${esc(p.forehand||'还未填写')}<br>反手 · ${esc(p.backhand||'还未填写')}</div><span class="link">认识这位球友${icon('arrow')}</span></a>`).join('')}</div>${!list.length?empty('没有找到这位球友','换个关键词再试试。',null):''}`}
function matchCard(m){const me=state.user?.id;let actions='',hint='';const mine=[m.a_id,m.b_id].includes(me);const [baseLabel,cls]=statuses[m.status];const label=m.status==='completed'?(m.settled_at?'已结算':'待00:00结算'):baseLabel;if(mine){if(m.status==='invited'){if(m.b_id===me){actions=`<button class="btn outline small" data-action="match" data-id="${m.id}" data-op="decline">婉拒</button><button class="btn small" data-action="match" data-id="${m.id}" data-op="accept">${icon('check')}接受邀请</button>`;hint='由对方发起，等待你的回应'}else{hint='邀请已发出，等待对方接受';actions=`<button class="btn outline small" data-action="match" data-id="${m.id}" data-op="cancel">撤回邀请</button>`}}if(m.status==='accepted'){hint='双方已同意；可随时提交赛果，无需等待预约时间';actions=`${m.event_id?'':`<button class="btn outline small" data-action="match" data-id="${m.id}" data-op="cancel">取消对战</button>`}<button class="btn small" data-action="report" data-id="${m.id}">提交赛果${icon('arrow')}</button>`}if(m.status==='reported'){if(m.reporter_id===me){hint=m.event_id?'成绩已录入比分表，未确认成绩将在00:00自动确认并结算':'你已提交比分，等待对方确认'}else{hint='请核对每局比分，确认后进入今晚00:00的积分结算队列';actions=`<button class="btn outline small" data-action="match" data-id="${m.id}" data-op="reject">比分有误，退回</button><button class="btn small" data-action="confirm" data-id="${m.id}">${icon('check')}确认赛果</button>`}}}if(m.event_id&&state.user?.role==='admin'&&['accepted','reported','completed'].includes(m.status))actions+=`<button class="btn outline small" data-action="event-result" data-id="${m.id}" data-event="${m.event_id}">修改比赛结果</button>`;if(m.status==='completed'&&!m.event_id&&state.user?.role==='admin')actions+=`<button class="btn danger small" data-action="void" data-id="${m.id}">作废并重算</button>`;const delta=(d)=>d==null?'':`<span class="delta ${d<0?'negative':''}">${d>0?'+':''}${d}</span>`;return `<article class="panel match-card"><div class="match-card-top"><div class="eyebrow">MATCH ${String(m.id).padStart(4,'0')} <span>·</span> ${best(m.best_of)}</div><span class="badge ${cls}">${label}</span></div><div class="vs-row"><a class="side" href="#player/${m.a_id}">${avatar({id:m.a_id,name:m.a_name,avatar_version:m.a_avatar_version})}<span>${esc(m.a_name)} ${m.status==='completed'?delta(m.a_delta):''}</span></a><span class="vs-score">${m.score_a==null?'VS':m.score_a+' : '+m.score_b}</span><a class="side" href="#player/${m.b_id}"><span>${esc(m.b_name)} ${m.status==='completed'?delta(m.b_delta):''}</span>${avatar({id:m.b_id,name:m.b_name,avatar_version:m.b_avatar_version})}</a></div>${m.forfeit_reason?`<div class="notice warn">${esc(m.forfeit_reason)}${m.winner_id?'，弃权双方个人积分不变。':'，双方记败场，个人积分不变。'}</div>`:''}${m.games?`<div class="game-chips">${JSON.parse(m.games).map((g,i)=>`<span>第${i+1}局 ${g[0]}:${g[1]}</span>`).join('')}</div>`:''}<div class="meta"><span>${icon('calendar')}</span><span>${when(m.scheduled_at,true)}</span><span>地点 · ${esc(m.venue)}</span>${m.confirmed_at?`<span>${when(m.confirmed_at)} 确认${m.settled_at?' · '+when(m.settled_at)+'结算':''}</span>`:''}</div>${m.note?`<p class="hint">备注：${esc(m.note)}</p>`:''}${m.void_reason?`<div class="notice warn">作废原因：${esc(m.void_reason)}。此场作废，个人积分将在00:00统一重算。</div>`:''}${actions||hint?`<div class="match-actions"><span class="match-hint">${hint}</span>${actions}</div>`:''}</article>`}
function singleMatchPage(){let list=tab==='all'?state.matches:state.mine;const pending=['invited','accepted','reported'];if(tab==='pending')list=list.filter(m=>pending.includes(m.status));if(tab==='completed')list=list.filter(m=>m.status==='completed');return `${head('下一场，你来开球。','邀请需要对方同意；赛果需要另一方确认。每一分，都公开透明。','CHALLENGE. PLAY. REPEAT.')}${matchTypeTabs()}<div class="filters"><div class="tabs" role="group" aria-label="对战筛选">${[['all','全站赛果'],['mine','我的对战'],['pending','等待回应 / 进行中'],['completed','我的已完成']].map(([id,label])=>`<button class="tab ${tab===id?'selected':''}" data-action="match-tab" data-tab="${id}">${label}</button>`).join('')}</div></div>${tab!=='all'&&!state.user?gate():list.length?list.map(matchCard).join(''):`<section class="panel">${empty('球台已就位，就等你了',tab==='all'?'还没有已确认赛果，来创造第一场精彩。':'这里会显示你的对战、邀请和待确认赛果。')}</section>`}<p class="hint">${tab==='all'?'展示最近200场已确认或作废的比赛。':'展示你最近100场对战。'}积分每日北京时间00:00按确认顺序结算。</p>`}
const gate=()=>`<div class="panel auth-gate form-panel"><div class="empty-icon">${icon('paddle')}</div><h2>你的球台，等你入场。</h2><p>登录后可以发起对战、回应邀请、保存球拍配置，<br>也能记录属于你的每一次进步。</p><button class="btn" data-action="login">登录 / 加入俱乐部${icon('arrow')}</button></div>`;
function gearForm(u){return `<form data-form="gear"><div class="field"><label for="blade">底板</label><input id="blade" name="blade" maxlength="120" placeholder="例如：蝴蝶 Viscaria" value="${esc(u.blade)}"></div><div class="row"><div class="field"><label for="forehand">正手胶皮</label><input id="forehand" name="forehand" maxlength="120" placeholder="例如：红双喜 狂飙3" value="${esc(u.forehand)}"></div><div class="field"><label for="backhand">反手胶皮</label><input id="backhand" name="backhand" maxlength="120" placeholder="例如：蝴蝶 Dignics 05" value="${esc(u.backhand)}"></div></div><div class="row"><div class="field"><label for="grip">握拍方式</label><select id="grip" name="grip">${['横板','直板'].map(x=>`<option ${u.grip===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="hand">持拍手</label><select id="hand" name="hand">${['右手','左手'].map(x=>`<option ${u.hand===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label for="bio">一句话介绍自己</label><textarea id="bio" name="bio" maxlength="200" placeholder="聊聊你的打法，或想约球的时间…">${esc(u.bio)}</textarea></div><div class="form-error" role="alert"></div><button class="btn" type="submit">保存球拍配置${icon('check')}</button></form>`}
function me(){const u=state.user;if(!u)return gate();return `${head('我的乒乓日常。','装备、积分、每一场好球，都在这里。','YOUR PERSONAL CLUBHOUSE',false)}<div class="profile-hero panel"><button class="avatar-upload" data-action="pick-avatar" aria-label="上传或更换头像">${avatar(u,true)}<span class="avatar-camera">${icon('plus')}</span><small>更换头像</small></button><input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><div><h1>${esc(u.name)} ${u.role==='admin'?'<span class="badge">管理员</span>':''}</h1><div class="my-title">${titleBadge(u)}<button class="link" data-action="edit-title">${u.title?'修改称号':'设置我的称号'}${icon('plus')}</button></div><p>${esc(u.email)} · ${u.email_verified?'邮箱已验证':'密码账号'}</p></div><div class="profile-rating"><strong>${num(u.rating)}</strong><small>CLUB RATING</small></div></div><div class="two-col"><section class="panel"><div class="panel-title"><div><h2>${icon('paddle')}我的球拍配置</h2><p>好装备是伙伴，好球友也是</p></div></div><div class="profile-body">${gearForm(u)}</div></section><div><section class="panel"><div class="panel-title"><h2>${icon('shield')}账号与安全</h2></div><div class="profile-body"><p class="hint">注册时的账号恢复码可以重置密码，请妥善保存。邮箱验证码${state.mail_ready?'已启用，可用于登录':'发信服务尚未接通，当前使用密码登录'}。</p>${u.role==='admin'?`<div class="equipment-row"><span>俱乐部管理</span>${link('进入管理室','admin')}</div>`:''}<div class="equipment-row"><span>赛事系统</span>${link('赛事大厅','events')}</div><div class="equipment-row"><span>积分与隐私</span>${link('查看规则','rules')}</div><div class="equipment-row"><span>管理登录密码</span><button class="link" data-action="password">修改密码${icon('chevron')}</button></div><div class="equipment-row"><span>对战邀请 / 赛果</span>${link('查看我的对战','matches')}</div><div class="equipment-row"><span>个人公开档案</span>${link('查看主页','player/'+u.id)}</div><div class="equipment-row"><span>当前设备</span><button class="link danger-text" data-action="logout">退出登录${icon('logout')}</button></div></div></section><div class="new-here"><h3>先尊重对手，再享受比赛。</h3><p>友好约球，如实报分。不能赴约时，<br>提前与对手沟通并取消邀请。</p></div></div></div>`}
function profile(data){const p=data.player,ms=data.matches.filter(m=>m.status==='completed'),wins=ms.filter(m=>m.winner_id===p.id).length;
const deductions=data.inactivity||[];
const history=[...deductions.map(d=>({...d,effective_at:d.due_at})),...data.history].sort((a,b)=>new Date(a.effective_at)-new Date(b.effective_at));
const inactivity=deductions.length?`<div class="rules-body"><h3>未参赛扣分</h3>${deductions.slice(-3).reverse().map(d=>`<div class="equipment-row"><span>${esc(eventTime(d.due_at))}</span><strong>${d.delta} 分</strong></div>`).join('')}</div>`:'';
return `${head('球友档案','了解对手，也认识一位新朋友。','PLAYER PROFILE',false)}<section class="profile-hero panel">${avatar(p,true)}<div><h1>${esc(p.name)} ${p.role==='admin'?'<span class="badge">管理员</span>':''}</h1>${titleBadge(p)}<p>${esc(p.bio||'热爱乒乓，期待和你切磋。')}</p><p>${esc(p.grip)} · ${esc(p.hand)} · ${day(p.created_at)}加入</p></div><div class="profile-rating"><strong>${num(p.rating)}</strong><small>CLUB RATING</small></div></section><div class="two-col"><div><section class="panel"><div class="panel-title"><h2>积分轨迹</h2><span class="hint">${history.length}次积分变动 · 1500 分起步</span></div><div class="history-chart">${sparkline(history,true)}<div class="chart-legend"><span>1500 · 初始积分</span><span>${num(p.rating)} · 当前积分</span></div></div>${inactivity}</section><section class="panel"><div class="panel-title"><h2>对战记录</h2><span class="hint">最近100场内胜场 ${wins} / ${ms.length}</span></div>${data.matches.length?`<div class="feed">${data.matches.slice(0,10).map(m=>m.status==='completed'?mini(m):`<p class="notice">对战 #${m.id} 已作废：${esc(m.void_reason)}</p>`).join('')}</div>`:empty('第一场好球，未来可期','这位球友还没有已确认的比赛。',null)}</section></div><section class="panel"><div class="panel-title"><h2>${icon('paddle')}随身装备</h2></div><div class="profile-body">${[['底板',p.blade],['正手胶皮',p.forehand],['反手胶皮',p.backhand],['握拍方式',p.grip],['持拍手',p.hand]].map(([a,b])=>`<div class="equipment-row"><span>${a}</span><strong>${esc(b||'尚未填写')}</strong></div>`).join('')}<button class="btn full" data-action="invite" data-id="${p.id}">约一场好球${icon('arrow')}</button></div></section></div>`}
const bands=[[0,12,8,8],[13,37,7,10],[38,62,6,13],[63,87,5,16],[88,112,4,20],[113,137,3,25],[138,162,2,30],[163,187,2,35],[188,212,1,40],[213,237,1,45],[238,null,0,50]];
function rules(){return `${head('让每一分，有据可循。','校内独立积分，单场换算参考开球网 ChinaTT 公开积分表。','FAIR PLAY. CLEAR RULES.',false)}<div class="two-col"><section class="panel"><div class="panel-title"><div><h2>单打积分换算表</h2><p>胜方加分 = 负方扣分，取决于结算时的双方积分差</p></div></div><div class="table-wrap"><table><thead><tr><th>积分差（含边界）</th><th>高分者胜 / 得失分</th><th>低分者胜 / 得失分</th></tr></thead><tbody>${bands.map(([a,b,x,y])=>`<tr><td>${b==null?'≥ '+a:a+'–'+b}</td><td>± ${x}</td><td>± ${y}</td></tr>`).join('')}</tbody></table></div><div class="rules-body"><h3>举个例子</h3><p>双方均为 1500 分：胜者 1508，负者 1492。<br>2000 对 1950：高分者胜得 6 分；低分者爆冷胜得 13 分。3:0 和 3:2 的单场积分变化相同。</p><h3>来源与适用范围</h3><p>参考<a href="https://kaiqiuwang.cc/home/space-24-do-blog-id-1124.html" target="_blank" rel="noopener noreferrer">《ChinaTT积分制度说明（2021年03月更新）》</a>的单场积分表。统一初始1500分按本俱乐部设定；不采用官方首次定级、年度积分及特殊人工调整，不与开球网账号同步。本站为独立社区项目。</p></div></section><div><section class="panel"><div class="panel-title"><h2>一场对战，如何计分？</h2></div><div class="rules-body"><h3>01 · 双方先同意</h3><p>任一用户均可发起单打邀请，选择时间、地点和赛制。对方接受后，对战才成立；取消或婉拒不影响积分。</p><h3>02 · 如实记录每局比分</h3><p>支持三局两胜、五局三胜、七局四胜。每局11分，10平后领先2分获胜。可提前报分，预约时间仅作安排参考，比赛结束后不再记录额外局。</p><h3>03 · 另一方确认，零点结算</h3><p>提交者不能确认自己的赛果。另一方可确认或退回，确认后进入待结算队列，每日北京时间00:00按确认顺序原子结算一次。多场比赛按确认顺序，使用当时最新积分。</p><h3>未参赛扣分</h3><p>从注册或最近一次确认赛果起算，每满一个月未打有效比赛，在北京时间零点扣 20 分。打完一场并确认赛果后重新起算，单打照常计分，双打也算参赛。仅报名、发出邀请或弃权不算参赛。</p><h3>04 · 错误可追溯</h3><p>双方有争议时请先退回赛果；已结算的比赛可由管理员注明原因作废，系统保留记录并在00:00依历史顺序重新计算后续积分。</p></div></section><section class="panel"><div class="panel-title"><h2>隐私与使用说明</h2></div><div class="rules-body"><p>昵称、积分、球拍配置和已结算对战为公开信息。普通约战的邀请和未确认赛果仅限参赛者与管理员查看；赛事赛程和比分公开。邮箱仅本人和管理员可见；密码以不可逆哈希保存。登录使用有效期14天的安全会话 Cookie。</p><h3>账号与公平使用</h3><p>邮箱验证码仅在发信服务接通后启用。密码注册不会自动验证邮箱归属；注册后请保存恢复码。禁止冒用身份、虚报赛果及批量刷分，管理员可停用违规账号。</p><h3>数据与联系</h3><p>系统每日备份数据库，备份保留14天。如需处理个人信息或对战争议，请联系俱乐部管理员${esc(state.club?.admin_name||'管理员')}。请勿在昵称或装备简介中填写敏感信息。</p></div></section></div></div>`}
function admin(){if(!state.user||state.user.role!=='admin')return gate();const a=state.admin;return `${head('俱乐部管理室。','公平、透明，让大家安心享受每一场对战。','ADMINISTRATION',false)}<div class="notice">只有管理员账号具备管理权限。作废比赛会保留原始记录并重算后续积分；停用用户将撤销其会话并取消未结束对战。</div><section class="panel"><div class="panel-title"><h2>用户管理</h2><span class="hint">${a.users.length} 个账号</span></div><div class="table-wrap admin"><table><thead><tr><th>用户</th><th>邮箱</th><th>身份 / 状态</th><th>管理</th></tr></thead><tbody>${a.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><span class="badge ${u.active?'':'muted'}">${u.role==='admin'?'管理员':u.active?'普通用户':'已停用'}</span></td><td>${u.role==='admin'?'—':`<button class="btn ${u.active?'danger':'outline'} small" data-action="user-state" data-id="${u.id}" data-active="${u.active?'0':'1'}">${u.active?'停用账号':'恢复账号'}</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-title"><h2>操作审计</h2>${link('管理比赛赛果','matches')}</div><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象</th></tr></thead><tbody>${a.audit.map(x=>`<tr><td>${when(x.created_at)}</td><td>${esc(x.actor_name)}</td><td>${esc(x.action)}</td><td>${esc(x.target)}</td></tr>`).join('')}</tbody></table></div>${!a.audit.length?empty('管理记录将在这里留存','每一次邀请、确认和管理操作，都有迹可循。',null,'','shield'):''}</section>`}
async function render(){const seq=++loadSequence,r=route();try{if(r.startsWith('player/')){shell('<div class="loading">正在读取球友档案…</div>');const data=await api('players/'+Number(r.split('/')[1]));if(seq===loadSequence){currentProfile=data;shell(profile(data))}return}const views={home,rankings,players,matches:matchPage,me,admin,rules};shell((views[r.split('/')[0]]||home)())}catch(e){shell(`<div class="panel">${empty('暂时没能读取页面',esc(e.message),'reload','重新加载')}</div>`)}}
function modal(title,subtitle,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal()}
const field=(label,name,type='text',placeholder='',required=true,attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${attrs}></div>`;
function auth(mode='login'){let fields='',title='',sub='',label='';if(mode==='register'){title='入场，一起打好球。';sub='从1500分开始，记录属于你的乒乓日常。';label='创建账号，加入俱乐部';fields=field('昵称','name','text','2–24个字符',true,'minlength="2" maxlength="24" autocomplete="nickname"')+field('邮箱','email','email','你的常用邮箱',true,'autocomplete="email" maxlength="254"')+field('设置密码','password','password','至少10个字符',true,'minlength="10" maxlength="128" autocomplete="new-password"')+`<div class="notice">邮箱仅用于登录与账号管理，不会公开。注册即表示接受<a href="#rules/privacy" data-action="close">隐私与使用说明</a>。注册成功后请保存账号恢复码。</div>`}else if(mode==='otp'){title='好久不见，球友。';sub='用注册邮箱接收6位验证码。';label='验证并登录';fields=`<div class="tabs"><button type="button" class="tab" data-action="login">密码登录</button><button type="button" class="tab selected" data-action="otp">邮箱验证码</button></div>${state.mail_ready?'':`<div class="notice warn">发信服务尚未配置，暂时请使用密码登录。</div>`}`+field('注册邮箱','email','email','name@example.com',true,'autocomplete="email"')+`<div class="field"><label for="f-code">6位验证码</label><div class="password-row"><input id="f-code" name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="one-time-code" required><button type="button" class="btn outline" data-action="send-code" ${state.mail_ready?'':'disabled'}>发送验证码</button></div><p class="field-hint">10分钟内有效，60秒可重发。尚未注册？请先创建账号。</p></div>`}else if(mode==='recover'){title='找回你的账号。';sub='使用注册时保存的恢复码重设密码。';label='重设密码';fields=field('邮箱','email','email','注册邮箱')+field('账号恢复码','recovery_code','text','注册成功时获得的恢复码')+field('新密码','password','password','至少10个字符',true,'minlength="10" maxlength="128" autocomplete="new-password"')}else{title='好久不见，球友。';sub='登录，继续属于你的每一场好球。';label='登录俱乐部';fields=`<div class="tabs"><button type="button" class="tab selected" data-action="login">密码登录</button><button type="button" class="tab" data-action="otp">邮箱验证码</button></div>`+field('邮箱或昵称','identity','text','输入你的邮箱或昵称',true,'autocomplete="username" maxlength="254"')+field('密码','password','password','输入密码',true,'autocomplete="current-password" maxlength="128"')+`<div class="auth-links"><span></span><button class="link" type="button" data-action="recover">忘记密码？使用恢复码</button></div>`}modal(title,sub,`<form data-form="${mode}">${fields}<div class="form-error" role="alert"></div><button class="btn full" type="submit" ${mode==='otp'&&!state.mail_ready?'disabled':''}>${label}${icon('arrow')}</button></form><div class="auth-switch">${mode==='register'?'已经是球友了？':'还没有账号？'}<button class="link" data-action="${mode==='register'?'login':'register'}">${mode==='register'?'去登录':'加入俱乐部'}</button></div>`)}
function invite(id){if(!state.user)return auth('login');if(Number(id)===state.user.id){tab='mine';location.hash='matches';render();return}const ops=state.players.filter(p=>p.id!==state.user.id);if(!ops.length){modal('第一位球友，欢迎你。','把俱乐部链接分享给朋友，一起开球。',`<div class="notice">其他球友注册后，就可以发起对战邀请。所有人初始积分均为1500。</div><button class="btn full" data-action="share">复制俱乐部链接${icon('arrow')}</button>`);return}const t=new Date(Date.now()+3600000);const local=new Date(t.getTime()-t.getTimezoneOffset()*60000).toISOString().slice(0,16);modal('约一场好球。','选择对手和时间，对方接受后，对战才正式成立。',`${inviteTypeTabs()}<form data-form="invite"><div class="field"><label for="opponent">邀请球友</label><select id="opponent" name="opponent_id">${ops.map(p=>`<option value="${p.id}" ${p.id===Number(id)?'selected':''}>${esc(p.name)} · ${p.rating}分</option>`).join('')}</select></div>${field('比赛时间 <small>按设备本地时区填写</small>','scheduled_at','datetime-local','',true,`value="${local}"`)}${field('比赛地点','venue','text','例如：利兹学院乒乓球室',true,'minlength="2" maxlength="100"')}<div class="field"><label for="best-of">赛制</label><select name="best_of" id="best-of"><option value="3">三局两胜</option><option value="5" selected>五局三胜</option><option value="7">七局四胜</option></select></div>${field('留言 <small>选填</small>','note','text','和球友说点什么…',false,'maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">发出邀请${icon('arrow')}</button></form>`)}
const findSingleMatch=id=>(route()===`event/${activeEvent?.id}`?activeEvent.matches.find(m=>m.id===Number(id)):undefined)??state.mine.find(m=>m.id===Number(id));
function report(mid,firstPlayer){
    const m=findSingleMatch(mid);
    if(!m)return;
    const reversed=Number(firstPlayer)===m.b_id;
    const left=reversed?{name:m.b_name,key:'b'}:{name:m.a_name,key:'a'};
    const right=reversed?{name:m.a_name,key:'a'}:{name:m.b_name,key:'b'};
    const guidance=m.event_id?'一人录入即可同步双方比分表，未确认成绩将在00:00自动确认并结算。':'须另一方确认后才计分。';
    modal('记录比赛成绩',`${esc(left.name)}（左） vs ${esc(right.name)}（右） · ${best(m.best_of)}`,`<form data-form="report" data-id="${mid}"><div class="notice">填写实际进行的每局比分。每局11分、10平后需领先2分。未进行的局留空。${guidance}</div>${Array.from({length:m.best_of},(_,i)=>`<div class="game-input"><label>第${i+1}局</label><input name="${left.key}${i}" aria-label="第${i+1}局${esc(left.name)}得分" type="number" min="0" max="199" placeholder="${esc(left.name)}"><span>∶</span><input name="${right.key}${i}" aria-label="第${i+1}局${esc(right.name)}得分" type="number" min="0" max="199" placeholder="${esc(right.name)}"></div>`).join('')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">${m.event_id?'保存成绩，同步比分表':'提交，等待对手确认'}${icon('arrow')}</button></form>`);
}
async function mutation(path,data,success){const result=await api(path,data);$('#modal').close();await refresh();await render();toast(success||result.message||'已保存');return result}
function confirmation(mid){const m=findSingleMatch(mid);modal('确认这场赛果？','确认后赛果公开展示，积分将在北京时间00:00统一结算。',`${matchCard({...m,reporter_id:state.user.id})}<button class="btn full" data-action="match" data-id="${mid}" data-op="confirm">比分无误，确认赛果${icon('check')}</button>`)}
function showRecovery(result){modal('请保存你的账号恢复码。','这是找回密码的凭据，仅在这里显示一次。',`<div class="notice">请将恢复码保存到密码管理器。不要分享给他人；它能用于重置你的账号密码。</div><div class="secret" id="recovery-secret">${esc(result.recovery_code)}</div><button class="btn full" data-action="copy-recovery">复制恢复码${icon('check')}</button><div class="auth-switch"><button class="link" data-action="close">我已妥善保存</button></div>`)}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;try{if(['login','register','otp','recover'].includes(a))return auth(a);if(a==='close')return $('#modal').close();if(a==='pick-avatar'){const input=$('#avatar-file');if(!input){location.hash='me';await render();$('#avatar-file')?.click()}else input.click();return}if(a==='save-avatar'){el.disabled=true;await mutation('profile/avatar',{image:pendingAvatar},'头像已更新');pendingAvatar='';return}if(a==='reload'){await refresh();return render()}if(a==='invite')return invite(id);if(a==='equipment'){if(!state.user)return auth('login');location.hash='me';return render()}if(a==='report')return report(id);if(a==='confirm')return confirmation(id);if(a==='match-tab'){tab=el.dataset.tab;return render()}if(a==='logout')return mutation('auth/logout',{},'已退出登录');if(a==='password')return modal('更换登录密码。','新密码生效后，其他设备将退出登录。',`<form data-form="password">${field('当前密码','old_password','password','',true,'autocomplete="current-password"')}${field('新密码','password','password','至少10个字符',true,'minlength="10" maxlength="128" autocomplete="new-password"')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">保存新密码</button></form>`);if(a==='void')return modal('作废比赛并重算积分。','记录会保留，已结算积分会在北京时间00:00依历史顺序重新计算。',`<form data-form="void" data-id="${id}">${field('作废原因','reason','text','请写明原因，至少4个字符',true,'minlength="4" maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn danger full" type="submit">确认作废并重算</button></form>`);if(a==='user-state')return modal(el.dataset.active==='1'?'恢复此账号？':'停用此账号？','停用后会撤销登录会话，并取消该用户未结束的对战。',`<button class="btn full" data-action="user-state-confirm" data-id="${id}" data-active="${el.dataset.active}">确认${el.dataset.active==='1'?'恢复':'停用'}</button>`);if(a==='copy-recovery'||a==='share'){await navigator.clipboard.writeText(a==='copy-recovery'?$('#recovery-secret').textContent:location.href.split('#')[0]);return toast('已复制，请妥善保存')}el.disabled=true;if(a==='match')await mutation('matches/'+id,{action:el.dataset.op});if(a==='user-state-confirm')await mutation('admin/user',{user_id:Number(id),active:el.dataset.active==='1'});if(a==='send-code'){const email=$('#f-email').value;if(!$('#f-email').checkValidity())return $('#f-email').reportValidity();const r=await api('auth/send-code',{email});toast(r.message);let remaining=60;const countdown=setInterval(()=>{remaining--;el.textContent=remaining+'秒后重发';if(!remaining||!el.isConnected){clearInterval(countdown);el.disabled=false;el.textContent='发送验证码'}},1000);return}}catch(err){toast(err.message)}finally{if(a!=='send-code')el.disabled=false;else if(el.textContent==='发送验证码')el.disabled=false}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,btn=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');error.textContent='';btn.disabled=true;try{let r;if(kind==='register'||kind==='login'||kind==='otp'){r=await api('auth/'+(kind==='otp'?'code-login':kind),data);$('#modal').close();await refresh();await render();if(r.recovery_code)showRecovery(r);else toast('欢迎回来，球友。')}else if(kind==='recover'){r=await api('auth/recover',data);showRecovery(r);toast(r.message)}else if(kind==='gear'){await mutation('profile',data,'球拍配置已保存')}else if(kind==='password'){await mutation('auth/password',data)}else if(kind==='invite'){await mutation('matches',{...data,opponent_id:Number(data.opponent_id),best_of:Number(data.best_of),scheduled_at:new Date(data.scheduled_at).toISOString()});tab='mine';location.hash='matches';render()}else if(kind==='report'){const m=findSingleMatch(form.dataset.id);const games=[];let blank=false;for(let i=0;i<m.best_of;i++){const a=data['a'+i],b=data['b'+i];if(a===''&&b===''){blank=true;continue}if(blank||a===''||b==='')throw Error('请按顺序完整填写每局双方比分，未进行的局留空');games.push([Number(a),Number(b)])}await mutation('matches/'+m.id,{action:'report',games})}else if(kind==='void'){await mutation('admin/void',{match_id:Number(form.dataset.id),reason:data.reason})}}catch(err){error.textContent=err.message}finally{btn.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;filter=e.target.value;render().then(()=>{const input=$('#search');input?.focus();try{input?.setSelectionRange(position,position)}catch{}})}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('hashchange',()=>{filter='';render();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('online',()=>{refresh().then(render).catch(()=>{})});
async function start(){try{await refresh();await render()}catch(e){shell(`<div class="panel">${empty('球台稍等，正在准备',esc(e.message),'reload','重新连接')}</div>`)}}
start();
let eventConnection=null,eventConnectionId=null,eventRevision=null;
let eventUpdatePending=false,eventUpdateRunning=false;
function watchEvent(id,revision){
    if(eventConnectionId===id)return;
    eventConnection?.close();
    eventConnection=null;
    eventConnectionId=id;
    eventRevision=revision;
    eventUpdatePending=false;
    if(id===null)return;
    eventConnection=new EventSource(`${API}events/${id}/stream`);
    eventConnection.onopen=()=>{if(eventConnectionId===id)syncEventChanges()};
    eventConnection.onmessage=message=>{
        if(eventConnectionId!==id)return;
        const next=Number(message.data);
        if(next===eventRevision)return;
        eventRevision=next;
        eventUpdatePending=true;
        syncEventChanges();
    };
}
async function syncEventChanges(){
    if(!eventUpdatePending||eventUpdateRunning||document.hidden||$('#modal').open)return;
    eventUpdatePending=false;
    eventUpdateRunning=true;
    let success=false;
    try{
        await refresh();
        await render();
        success=true;
    }catch{
        eventUpdatePending=true;
    }finally{
        eventUpdateRunning=false;
    }
    if(success&&eventUpdatePending)syncEventChanges();
}
$('#modal').addEventListener('close',syncEventChanges);
document.addEventListener('visibilitychange',syncEventChanges);


document.addEventListener('change',async e=>{if(e.target.id!=='avatar-file')return;const file=e.target.files?.[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择JPG、PNG或WebP格式的图片');if(file.size>8*1024*1024)throw Error('原图请小于8MB');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片无法读取，请换一张照片'));i.src=data});if(image.naturalWidth>16000||image.naturalHeight>16000)throw Error('图片尺寸太大，请先缩小图片');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');ctx.fillStyle='#eef1e2';ctx.fillRect(0,0,256,256);const size=Math.min(image.naturalWidth,image.naturalHeight);ctx.drawImage(image,(image.naturalWidth-size)/2,(image.naturalHeight-size)/2,size,size,0,0,256,256);const result=canvas.toDataURL('image/jpeg',.88);pendingAvatar=result.split(',')[1];modal('换个头像，认识你。','图片已居中裁剪并压缩，确认后保存。',`<img class="avatar-preview" src="${result}" alt="新头像预览"><div class="notice">支持JPG、PNG、WebP，原图不超过8MB。头像会公开显示在积分榜、球友档案及对战记录中。</div><button class="btn full" data-action="save-avatar">保存头像${icon('check')}</button><div class="auth-switch"><button class="link" data-action="pick-avatar">重新选择图片</button></div>`)}catch(error){toast(error.message)}finally{e.target.value=''}});

let matchType='single',statsTab='activity',activeEvent=null;
function rankBadge(index){return index<3?`<span class="medal ${['gold','silver','bronze'][index]}" aria-label="${['金牌第一名','银牌第二名','铜牌第三名'][index]}">${index+1}</span>`:String(index+1).padStart(2,'0')}
const pct=x=>Math.round(x*100)+'%';
const duelTypes={weekly:'周赛',selection:'选拔赛',open:'公开赛'};
const eventStates={open:'报名中',groups:'小组赛',knockout:'淘汰赛',completed:'已完赛',cancelled:'已取消'};
function statsRows(type,limit=100){const data=(state.analytics?.[type]||[]).slice(0,limit);if(!data.length)return empty('精彩记录，等你来创造','已确认的比赛会自动进入战绩统计。',null);return `<div class="stat-list">${data.map((r,i)=>{if(type==='activity')return `<div class="stat-item"><span class="stat-place">${rankBadge(i)}</span><a class="player-name" href="#player/${r.id}">${avatar(r)}<span>${esc(r.name)}<small>单打 ${r.singles} · 双打 ${r.doubles}</small></span></a><strong>${r.played}<small> 场</small></strong></div>`;if(['risers','fallers'].includes(type))return `<div class="stat-item"><span class="stat-place">${rankBadge(i)}</span><a class="player-name" href="#player/${r.player.id}">${avatar(r.player)}<span>${esc(r.player.name)}<small>已结算 ${r.played} 场单打</small></span></a><strong class="${r.delta>0?'positive':'negative'}">${r.delta>0?'+':''}${r.delta}<small> 分</small></strong></div>`;if(['benefactors','nemeses'].includes(type))return `<div class="stat-item"><span class="stat-place">${i+1}</span><div class="relation"><a href="#player/${r.player.id}">${esc(r.player.name)}</a><small>对阵 <a href="#player/${r.opponent.id}">${esc(r.opponent.name)}</a> · ${r.wins}胜 / ${r.played}场</small></div><strong>${pct(r.rate)}<small> 胜率</small></strong></div>`;if(type==='doubles_combos')return `<div class="stat-item"><span class="stat-place">${rankBadge(i)}</span><div class="relation"><span>${r.players.map(p=>`<a href="#player/${p.id}">${esc(p.name)}</a>`).join(' / ')}</span><small>${r.wins} 胜 / ${r.played} 场 · 固定组合战绩</small></div><strong>${pct(r.rate)}</strong></div>`;return `<div class="stat-item"><span class="stat-place">${rankBadge(i)}</span><div class="relation"><a href="#player/${r.player.id}">${esc(r.player.name)}</a><small>${r.wins}胜/${r.played}场${r.best_partner?` · 最佳搭档 ${esc(r.best_partner.name)}（${pct(r.best_partner_rate)} / ${r.best_partner_played}场）`:''}</small></div><strong>${pct(r.rate)}</strong></div>`}).join('')}</div>`}
function board(title,type,desc,limit=3){return `<section class="panel board"><div class="panel-title"><div><h2>${title}</h2><p>${desc}</p></div>${link('全榜','stats/'+type)}</div>${statsRows(type,limit)}</section>`}
function analyticsHome(){return `<a class="event-entry panel" href="#events"><span class="event-entry-icon">${icon('trophy')}</span><span><strong>赛事大厅</strong><small>周赛 · 选拔赛 · 小组循环与淘汰赛</small></span><span class="link">去参赛${icon('arrow')}</span></a><div class="section-heading"><div class="eyebrow">THE CLUB IN MOTION</div><h2>每一场，都留下故事。</h2><p>战绩确认后更新；个人积分每天北京时间00:00结算。</p></div><div class="two-col analytics-grid">${board('场次达人榜','activity','单打 + 双打，谁是俱乐部劳模？',5)}<div>${board('近两周 · 上升最多','risers','最近14天已结算单打的积分净增长')}${board('近两周 · 掉分最快','fallers','最近14天已结算单打的积分净下降')}</div>${board('福星榜','benefactors','谁遇见谁，赢球的概率最高？')}${board('苦主榜','nemeses','谁遇见谁，胜率最难突破？')}${board('双打组合胜率榜','doubles_combos','只看组合战绩，不变更个人积分')}${board('双打胜率 / 最佳搭档','doubles_players','不同搭档的双打总胜率与最佳拍档')}</div><p class="hint board-policy">至少1场已确认赛果即可上榜，胜率同时展示样本数；同胜率优先场次多者。福星榜列有胜场的对位，苦主榜列有负场的对位。作废比赛不计战绩。</p>`}
const originalHome=home;home=()=>originalHome()+analyticsHome();
function statsPage(){const titles={activity:'场次达人榜',risers:'近两周 · 上升最多',fallers:'近两周 · 掉分最快',benefactors:'福星榜',nemeses:'苦主榜',doubles_combos:'双打组合胜率榜',doubles_players:'双打胜率与最佳搭档'};const type=route().split('/')[1]||'activity';return `${head(titles[type]||'俱乐部统计','对阵胜率和双打只统计已确认、未作废赛果；积分变化以每天00:00的结算结果为准。','THE CLUB STATS',false)}<div class="filters"><div class="tabs stats-tabs">${Object.entries(titles).map(([key,v])=>`<a class="tab ${key===type?'selected':''}" href="#stats/${key}">${v}</a>`).join('')}</div></div><section class="panel">${statsRows(titles[type]?type:'activity')}</section><div class="notice">胜率至少1场即可上榜，请结合场次判断。同胜率按场次多者优先。近两周指最近14天已结算单打积分净变化，双打不计个人积分。</div>`}
function matchTypeTabs(){return `<div class="filters"><div class="tabs"><button class="tab ${matchType==='single'?'selected':''}" data-action="match-type" data-type="single">单打</button><button class="tab ${matchType==='double'?'selected':''}" data-action="match-type" data-type="double">双打</button><a class="tab" href="#events">赛事大厅${icon('trophy')}</a></div><a class="link" href="#stats/doubles_combos">双打胜率榜${icon('arrow')}</a></div>`}
function inviteTypeTabs(){return `<div class="tabs"><button class="tab selected" data-action="invite">单打约战</button><button class="tab" data-action="double-invite">双打约战</button></div>`}
function matchPage(){return matchType==='double'?doubleMatchPage():singleMatchPage()}
function doublesCard(m){const ids=[m.a1,m.a2,m.b1,m.b2],me=state.user?.id,mine=ids.includes(me),consent=m.consents.find(x=>x.user_id===me),accepted=m.consents.filter(x=>x.accepted).length,confirmed=m.consents.filter(x=>x.confirmed).length;let actions='',hint='双打只记录胜率，不计个人积分';const team=keys=>`<div class="duo-team">${keys.map(key=>`<a href="#player/${m[key]}">${avatar({id:m[key],name:m[key+'_name'],avatar_version:m[key+'_avatar_version']})}<span>${esc(m[key+'_name'])}</span></a>`).join('')}</div>`;if(mine){if(m.status==='invited'){hint=`${accepted}/4人同意 · 四人同意后对战成立`;if(!consent?.accepted)actions=`<button class="btn outline small" data-action="double-action" data-id="${m.id}" data-op="decline">婉拒</button><button class="btn small" data-action="double-action" data-id="${m.id}" data-op="accept">接受邀请</button>`;else actions=`<button class="btn outline small" data-action="double-action" data-id="${m.id}" data-op="cancel">取消对战</button>`}if(m.status==='accepted')actions=`<button class="btn outline small" data-action="double-action" data-id="${m.id}" data-op="cancel">取消对战</button><button class="btn small" data-action="double-report" data-id="${m.id}">提交比分</button>`;if(m.status==='reported'){hint=`${confirmed}/4人已确认赛果`;if(!consent?.confirmed)actions=`<button class="btn outline small" data-action="double-action" data-id="${m.id}" data-op="reject">比分有误</button><button class="btn small" data-action="double-confirm" data-id="${m.id}">确认赛果</button>`}}if(m.status==='completed'&&state.user?.role==='admin')actions+=`<button class="btn danger small" data-action="double-void" data-id="${m.id}">作废战绩</button>`;return `<article class="panel match-card"><div class="match-card-top"><div class="eyebrow">DOUBLES ${String(m.id).padStart(4,'0')} · ${best(m.best_of)}</div><span class="badge ${statuses[m.status][1]}">${m.status==='completed'?'已确认战绩':statuses[m.status][0]}</span></div><div class="vs-row doubles-vs">${team(['a1','a2'])}<strong class="vs-score">${m.score_a==null?'VS':m.score_a+' : '+m.score_b}</strong>${team(['b1','b2'])}</div>${m.forfeit_reason?`<div class="notice warn">${esc(m.forfeit_reason)}${m.winner_id?'，弃权双方个人积分不变。':'，双方记败场，个人积分不变。'}</div>`:''}${m.games?`<div class="game-chips">${JSON.parse(m.games).map((g,i)=>`<span>第${i+1}局 ${g[0]}:${g[1]}</span>`).join('')}</div>`:''}<div class="meta"><span>${when(m.scheduled_at,true)}</span><span>${esc(m.venue)}</span><span>${esc(m.note)}</span></div>${m.void_reason?`<div class="notice warn">已作废：${esc(m.void_reason)}</div>`:''}<div class="match-actions"><span class="match-hint">${hint}</span>${actions}</div></article>`}
function doubleMatchPage(){let list=tab==='all'?(state.doubles||[]):(state.mine_doubles||[]);if(tab==='pending')list=list.filter(m=>['invited','accepted','reported'].includes(m.status));if(tab==='completed')list=list.filter(m=>m.status==='completed');return `${head('找个搭档，一起好球。','四人同意开打，四人确认赛果。只记录组合胜率，个人积分不变。','DOUBLES, DOUBLE THE FUN')}${matchTypeTabs()}<div class="filters"><div class="tabs">${[['all','全站双打'],['mine','我的双打'],['pending','等待回应 / 进行中'],['completed','已完成']].map(([id,label])=>`<button class="tab ${tab===id?'selected':''}" data-action="match-tab" data-tab="${id}">${label}</button>`).join('')}</div><button class="btn small" data-action="double-invite">${icon('plus')}双打约战</button></div>${tab!=='all'&&!state.user?gate():list.length?list.map(doublesCard).join(''):`<section class="panel">${empty('好搭档，一起找到','邀请三位球友，开一场双打。','double-invite','发起双打约战')}</section>`}`}
function doubleInvite(){if(!state.user)return auth('login');const ops=state.players.filter(p=>p.id!==state.user.id);if(ops.length<3)return modal('双打需要四位球友。','再邀请朋友加入，就能组队开打。','<div class="notice">需要发起者、搭档和两位对手，共四个不同账号。普通单打仍可以随时发起。</div>');const opt=(index)=>ops.map((p,i)=>`<option value="${p.id}" ${i===index?'selected':''}>${esc(p.name)}</option>`).join('');const t=new Date(Date.now()+3600000),local=new Date(t-t.getTimezoneOffset()*60000).toISOString().slice(0,16);modal('组队，双倍快乐。','四人同意后才成立，比赛不会改变个人积分。',`<div class="tabs"><button class="tab" data-action="invite">单打约战</button><button class="tab selected" data-action="double-invite">双打约战</button></div><form data-form="double-invite"><div class="field"><label>我的搭档</label><select name="partner_id" aria-label="我的搭档">${opt(0)}</select></div><div class="row"><div class="field"><label>对手一</label><select name="opponent1_id" aria-label="对手一">${opt(1)}</select></div><div class="field"><label>对手二</label><select name="opponent2_id" aria-label="对手二">${opt(2)}</select></div></div>${field('计划时间 <small>仅作参考，可提前报分</small>','scheduled_at','datetime-local','',true,`value="${local}"`)}${field('地点','venue','text','例如：利兹学院乒乓球室',true,'minlength="2" maxlength="100"')}<div class="field"><label>赛制</label><select name="best_of" aria-label="双打赛制"><option value="3">三局两胜</option><option value="5" selected>五局三胜</option><option value="7">七局四胜</option></select></div>${field('留言','note','text','选填',false,'maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">邀请三位球友${icon('arrow')}</button></form>`)}
function doubleReport(id){const m=state.mine_doubles.find(x=>x.id===Number(id));if(!m)return;modal('记录双打赛果。',`${esc(m.a1_name)} / ${esc(m.a2_name)}（左） vs ${esc(m.b1_name)} / ${esc(m.b2_name)}（右）`,`<form data-form="double-report" data-id="${id}"><div class="notice">填写已进行的局数，未进行的留空。提交后还需其余三位参赛者确认。</div>${Array.from({length:m.best_of},(_,i)=>`<div class="game-input"><label>第${i+1}局</label><input name="a${i}" aria-label="第${i+1}局左方得分" type="number" min="0" max="199"><span>:</span><input name="b${i}" aria-label="第${i+1}局右方得分" type="number" min="0" max="199"></div>`).join('')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">提交比分，等待其余三人确认</button></form>`)}
const eventTime=x=>new Date(x).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'})+'（北京时间）';
function eventList(){return `${head('把每一场，打成经典。','周赛、选拔赛与公开赛。报名参赛，赢下属于你的荣誉。','THE LEEDS TOURNAMENTS',false)}${state.user?.role==='admin'?'<button class="btn event-create-btn" data-action="event-create">'+icon('plus')+'创建赛事</button>':''}<div class="grid-3">${(state.events||[]).map(e=>`<a class="panel event-card" href="#event/${e.id}"><div class="event-card-top"><span class="badge">${duelTypes[e.kind]}${e.qualifiers===0?' · 大循环':''}</span><span class="hint">${eventStatus(e)}</span></div><h2>${esc(e.title)}</h2><p>${esc(e.description||'以球会友，每一场都值得认真。')}</p><div class="meta"><span>${eventTime(e.starts_at)}</span><span>${e.participants}人报名</span></div><div class="event-card-bottom"><span>${esc(e.venue)}</span><span class="link">${e.champion_name?'冠军 · '+esc(e.champion_name):'进入赛事'}${icon('arrow')}</span></div></a>`).join('')}</div>${!state.events?.length?`<section class="panel">${empty('下一场赛事，等你开场','管理员可创建周赛、选拔赛，自定义小组与晋级人数。',state.user?.role==='admin'?'event-create':null,'创建赛事','trophy')}</section>`:''}`}
function eventStatus(event){
    if(event.status==='open'&&!event.registration_open)return '报名已截止';
    if(event.status==='groups'&&event.qualifiers===0)return '大循环进行中';
    return eventStates[event.status];
}
function eventView(e){const admin=state.user?.role==='admin',enrolled=e.entries.some(p=>p.user_id===state.user?.id),roundRobin=e.qualifiers===0;
const bestOf=best(e.best_of);const playerName=id=>esc(e.entries.find(p=>p.user_id===id)?.name||'待前轮胜者');const groupName=n=>String.fromCharCode(65+n);return `${head(esc(e.title),`${duelTypes[e.kind]} · ${eventTime(e.starts_at)} · ${esc(e.venue)}`,'THE CLUB TOURNAMENT',false)}<div class="event-toolbar"><span class="badge">${eventStatus(e)}</span><span class="hint">${e.entries.length}位球友 · ${bestOf} · ${roundRobin?'单打大循环':`${e.group_count}组 · 每组前${e.qualifiers}名晋级`}</span>${e.registration_open?`<button class="btn small" data-action="event-action" data-id="${e.id}" data-op="${enrolled?'leave':'join'}">${enrolled?'退出报名':'报名参赛'}</button>`:''}${admin&&roundRobin&&e.status==='open'&&!e.registration_open?`<button class="btn small" data-action="event-draw" data-id="${e.id}">生成大循环赛程</button>`:''}${admin&&!roundRobin&&e.status==='open'?`<button class="btn small outline" data-action="event-seeds" data-id="${e.id}">设置种子</button><button class="btn small" data-action="event-draw" data-id="${e.id}">自动分组 / 生成循环赛</button>`:''}${admin&&e.status==='groups'?`<button class="btn small danger" data-action="event-absence" data-id="${e.id}">标记缺席 / 自动判负</button>`:''}${admin&&!roundRobin&&e.status==='groups'?`<button class="btn small" data-action="event-advance" data-id="${e.id}">设置晋级 / 生成淘汰赛</button>`:''}${admin&&e.status!=='cancelled'?`<button class="btn small danger" data-action="event-cancel" data-id="${e.id}">取消赛事</button>`:''}</div>${e.champion_id?`<div class="champion-banner">${icon('trophy')}本届冠军 · ${playerName(e.champion_id)}</div>`:''}${e.cancel_reason?`<div class="notice warn">赛事已取消：${esc(e.cancel_reason)}</div>`:''}<div class="notice">${e.description?`${esc(e.description)}<br>`:''}${e.rating_ceiling?`报名时个人积分须低于${e.rating_ceiling}分。<br>`:''}${roundRobin?'每两位参赛球友交手一次，全部赛果确认后按循环赛排名决出冠军。':'报名即同意本赛事生成的对战安排。'}管理员可标记缺席，未报分对战自动判负。赛事只需一人录入成绩，比分表即时更新；未确认成绩在北京时间00:00自动确认并结算。名次依次比较胜场、同胜场相互胜场、净胜局、净得分、种子或报名顺序。</div><section class="panel"><div class="panel-title"><h2>参赛球友</h2><span class="hint">${e.entries.length}人${roundRobin?'':' · 已标注种子'}</span></div><div class="entrant-list">${e.entries.map(p=>`<a href="#player/${p.user_id}" class="entrant">${avatar({id:p.user_id,name:p.name,avatar_version:p.avatar_version})}<span>${esc(p.name)}${p.absent_reason?' <small>缺席</small>':''}${p.seed?`<small>种子 #${p.seed}</small>`:''}</span></a>`).join('')||'<p class="empty">还没有报名，来成为第一位参赛球友。</p>'}</div></section>${eventMatrix(e)}${e.groups.length?`<div class="section-heading"><h2>${roundRobin?'大循环排名与赛程':'小组赛积分与赛程'}</h2></div><div class="grid-3">${e.groups.map(g=>`<section class="panel"><div class="panel-title"><h2>${roundRobin?'全体参赛球友':`${groupName(g.number)}组`}</h2>${roundRobin?'':`<span class="badge">前${e.qualifiers}名晋级</span>`}</div><div class="table-wrap"><table><thead><tr><th>球友</th><th>胜 / 场</th><th>净局</th></tr></thead><tbody>${g.standings.map((p,i)=>`<tr><td>${i+1}. ${esc(p.name)}${p.absent_reason?' <small>缺席</small>':''}${p.seed?` <span class="badge">#${p.seed}</span>`:''}</td><td>${p.wins} / ${p.played}</td><td>${p.game_diff>0?'+':''}${p.game_diff}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}</div><div class="event-fixtures">${e.matches.filter(m=>m.phase==='group').map(m=>`<div><p class="fixture-title">${roundRobin?'大循环':`${groupName(m.group_no)}组 · 小组循环赛`}</p>${matchCard(m)}</div>`).join('')}</div>`:''}${e.bracket.length?`<div class="section-heading"><h2>淘汰赛晋级之路</h2><p>胜者自动进入下一轮，轮空自动晋级；每轮比分由参赛双方确认。</p></div>${[...new Set(e.bracket.map(b=>b.round_no))].map(rnd=>`<section class="knockout-round"><h3>第${rnd}轮${rnd===Math.max(...e.bracket.map(b=>b.round_no))?' · 决赛':''}</h3><div class="event-fixtures">${e.bracket.filter(b=>b.round_no===rnd).map(b=>{const m=e.matches.find(m=>m.id===b.match_id);return m?matchCard(m):`<div class="panel bye-card"><span>${playerName(b.a_id)} vs ${b.b_id?playerName(b.b_id):b.winner_id?'轮空':'待前轮胜者'}</span><span class="badge">${b.winner_id?'已晋级':'等待前轮'}</span></div>`}).join('')}</div></section>`).join('')}`:''}`}
function createEvent(){const local=new Date(Date.now()+86400000+8*3600000).toISOString().slice(0,16);modal('举办一场新赛事。','开放报名后生成赛程。大循环选择一组，晋级人数填 0。',`<form data-form="event-create">${field('赛事名称','title','text','例如：利兹乒乓周末挑战赛',true,'minlength="2" maxlength="60"')}<div class="row"><div class="field"><label>类型</label><select name="kind" aria-label="赛事类型"><option value="weekly">周赛</option><option value="selection">选拔赛</option><option value="open">公开赛</option></select></div><div class="field"><label>赛制</label><select name="best_of" aria-label="赛事赛制"><option value="3">三局两胜</option><option value="5" selected>五局三胜</option><option value="7">七局四胜</option></select></div></div>${field('计划开赛时间（北京时间）','starts_at','datetime-local','',true,`value="${local}"`)}${field('地点','venue','text','比赛地点',true,'minlength="2" maxlength="100"')}<div class="row">${field('小组数','group_count','number','',true,'min="1" max="16" value="2"')}${field('每组晋级人数','qualifiers','number','',true,'min="0" max="8" value="2"')}</div>${field('报名积分上限（不含）','rating_ceiling','number','不限',false,'min="1" max="9999"')}${field('赛事说明','description','text','选填',false,'maxlength="500"')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">创建并开放报名</button></form>`)}
const previousRender=render;render=async()=>{const r=route();if(!r.startsWith('event/'))watchEvent(null,null);if(r==='events'){shell(eventList());return}if(r.startsWith('stats/')){shell(statsPage());return}if(r.startsWith('event/')){const seq=++loadSequence;shell('<div class="loading">正在准备赛事赛程…</div>');try{const e=await api('events/'+Number(r.split('/')[1]));if(seq!==loadSequence)return;activeEvent=e;for(const m of e.matches)if([m.a_id,m.b_id].includes(state.user?.id)&&!state.mine.some(x=>x.id===m.id))state.mine.push(m);shell(eventView(e));watchEvent(e.id,e.revision)}catch(err){shell(`<div class="panel">${empty('赛事暂不可用',esc(err.message),'reload','重新加载')}</div>`)}return}return previousRender()};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const act=el.dataset.action,id=Number(el.dataset.id);try{if(act==='match-type'){matchType=el.dataset.type;return render()}if(act==='double-invite')return doubleInvite();if(act==='double-report')return doubleReport(id);if(act==='double-confirm'){const m=state.mine_doubles.find(m=>m.id===id);return modal('确认双打赛果？','四人全部确认后才进入组合胜率榜，个人积分不变。',`${doublesCard({...m,status:'completed'})}<button class="btn full" data-action="double-action" data-id="${id}" data-op="confirm">比分无误，确认赛果</button>`)}if(act==='double-void')return modal('作废双打战绩。','记录会保留，组合与个人双打胜率将重新统计。',`<form data-form="double-void" data-id="${id}">${field('作废原因','reason','text','至少4个字符',true,'minlength="4" maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn danger full" type="submit">确认作废</button></form>`);if(act==='event-create'){if(state.user?.role!=='admin')return toast('只有管理员可以创建赛事');return createEvent()}if(act==='event-seeds'){return modal('设置赛事种子。','只对已报名球友设置；留空表示非种子，编号不可重复。',`<form data-form="event-seeds" data-id="${id}">${activeEvent.entries.map(p=>`<div class="equipment-row"><label for="seed-${p.user_id}">${esc(p.name)}</label><input id="seed-${p.user_id}" name="seed-${p.user_id}" type="number" min="1" max="128" placeholder="非种子" value="${p.seed||''}"></div>`).join('')}<div class="form-error" role="alert"></div><button class="btn full" type="submit">保存种子</button></form>`)}if(act==='event-draw'&&activeEvent.qualifiers===0)return modal('生成大循环赛程？','生成后结束报名，每两位参赛球友交手一次。',`<button class="btn full" data-action="event-action" data-op="draw" data-id="${id}">确认生成赛程</button>`);if(act==='event-draw')return modal('生成小组循环赛？','种子按蛇形分布，非种子随机分入各组；生成后结束报名。',`<div class="notice">共${activeEvent.entries.length}人，${activeEvent.group_count}组。每组至少两人，人数差最多1人。小组内每两人交手一次。</div><button class="btn full" data-action="event-action" data-op="draw" data-id="${id}">确认分组并生成赛程</button>`);if(act==='event-advance')return modal('设置小组晋级。','所有小组赛确认后，按排名选取每组前几名进入淘汰赛。',`<form data-form="event-advance" data-id="${id}">${field('每组晋级人数','qualifiers','number','',true,`min="1" max="8" value="${activeEvent.qualifiers}"`)}<div class="notice">人数不足满签时自动轮空；胜者会在赛果确认后自动进入下一轮。</div><div class="form-error" role="alert"></div><button class="btn full" type="submit">生成淘汰赛</button></form>`);if(act==='event-cancel')return modal('取消整场赛事。','相关赛果会保留为作废记录，已结算个人积分于00:00重算。',`<form data-form="event-cancel" data-id="${id}">${field('取消原因','reason','text','至少4个字符',true,'minlength="4" maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn danger full" type="submit">确认取消赛事</button></form>`);if(act==='event-action'&&!state.user)return auth('login');if(act==='double-action'){el.disabled=true;await mutation('doubles/'+id,{action:el.dataset.op})}if(act==='event-action'){el.disabled=true;await mutation('events/'+id+'/'+el.dataset.op,{})}}catch(err){toast(err.message)}finally{el.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;const kind=f.dataset.form;if(!['double-invite','double-report','double-void','event-create','event-seeds','event-advance','event-cancel'].includes(kind))return;e.preventDefault();const d=Object.fromEntries(new FormData(f)),btn=f.querySelector('[type=submit]'),err=f.querySelector('.form-error');btn.disabled=true;err.textContent='';try{if(kind==='double-invite'){await mutation('doubles',{...d,partner_id:Number(d.partner_id),opponent1_id:Number(d.opponent1_id),opponent2_id:Number(d.opponent2_id),best_of:Number(d.best_of),scheduled_at:new Date(d.scheduled_at).toISOString()});matchType='double';tab='mine';location.hash='matches';render()}if(kind==='double-report'){const m=state.mine_doubles.find(m=>m.id===Number(f.dataset.id)),games=[];let blank=false;for(let i=0;i<m.best_of;i++){const a=d['a'+i],b=d['b'+i];if(a===''&&b===''){blank=true;continue}if(blank||a===''||b==='')throw Error('请按顺序完整填写每局双方比分');games.push([Number(a),Number(b)])}await mutation('doubles/'+m.id,{action:'report',games})}if(kind==='double-void')await mutation('admin/doubles-void',{match_id:Number(f.dataset.id),reason:d.reason});if(kind==='event-create'){const r=await mutation('events',{...d,starts_at:new Date(d.starts_at+'+08:00').toISOString(),best_of:Number(d.best_of),group_count:Number(d.group_count),qualifiers:Number(d.qualifiers),rating_ceiling:d.rating_ceiling?Number(d.rating_ceiling):null});location.hash='event/'+r.id;render()}if(kind==='event-seeds'){const seeds=Object.entries(d).filter(([k,v])=>k.startsWith('seed-')&&v!=='').map(([k,v])=>({user_id:Number(k.slice(5)),seed:Number(v)}));await mutation('events/'+f.dataset.id+'/seeds',{seeds})}if(kind==='event-advance')await mutation('events/'+f.dataset.id+'/advance',{qualifiers:Number(d.qualifiers)});if(kind==='event-cancel')await mutation('events/'+f.dataset.id+'/cancel',{reason:d.reason})}catch(error){err.textContent=error.message}finally{btn.disabled=false}});

function doubleNeedsReply(m){const c=m.consents.find(x=>x.user_id===state.user?.id);return c&&((m.status==='invited'&&!c.accepted)||(m.status==='reported'&&!c.confirmed))}

function titleBadge(p){return p?.title?`<span class="player-title" title="用户自定义称号">${esc(p.title)}</span>`:''}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action="edit-title"]');if(!el)return;if(!state.user)return auth('login');modal('给自己一个称号。','最多10个字，留空即可清除；只修改你自己的称号。',`<form data-form="title">${field('我的称号','title','text','例如：横板暴力熊',false,`maxlength="10" value="${esc(state.user.title||'')}"`)}<div class="field-hint">称号会显示在个人主页、球友列表和积分榜，不改变账号权限。</div><div class="form-error" role="alert"></div><button class="btn full" type="submit">保存称号</button></form>`)});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form="title"]');if(!f)return;e.preventDefault();const button=f.querySelector('[type="submit"]'),err=f.querySelector('.form-error');button.disabled=true;err.textContent='';try{const title=new FormData(f).get('title')||'';if([...title.normalize('NFKC').trim()].length>10)throw Error('称号最多10个字');await mutation('profile/title',{title})}catch(error){err.textContent=error.message}finally{button.disabled=false}});

function absenceModal(eid){
    const players=activeEvent.entries.filter(p=>!p.absent_reason);
    modal('标记赛事缺席','未报分对战将按弃权判负，五局三胜记0比3。已提交或确认的正常赛果保留。',`<form data-form="event-absence" data-id="${eid}"><div class="notice">双方均缺席时双方记败场，个人积分不变。所有弃权对战仅记赛事胜负，双方个人积分不加不减。</div>${players.map(p=>`<label class="equipment-row"><span>${esc(p.name)}</span><input type="checkbox" name="absent" value="${p.user_id}" aria-label="标记${esc(p.name)}缺席"></label>`).join('')}${field('缺席原因','reason','text','例如：报名后未到场',true,'minlength="2" maxlength="200"')}<div class="form-error" role="alert"></div><button class="btn danger full" type="submit">确认缺席并自动判负</button></form>`);
}
document.addEventListener('click',e=>{
    const button=e.target.closest('[data-action="event-absence"]');
    if(button&&state.user?.role==='admin')absenceModal(Number(button.dataset.id));
});
document.addEventListener('submit',async e=>{
    const form=e.target.closest('form[data-form="event-absence"]');
    if(!form)return;
    e.preventDefault();
    const button=form.querySelector('[type="submit"]');
    const error=form.querySelector('.form-error');
    button.disabled=true;
    try{
        const data=new FormData(form);
        const ids=data.getAll('absent').map(Number);
        if(!ids.length)throw Error('请选择至少一位缺席球员');
        await mutation(`events/${form.dataset.id}/absent`,{user_ids:ids,reason:data.get('reason')});
    }catch(err){error.textContent=err.message}finally{button.disabled=false}
});

function eventMatrix(event){
    if(!event.matches.length)return '';
    const players=event.entries;
    const cell=(row,col)=>{
        if(row.user_id===col.user_id)return '<td class="matrix-diagonal" aria-label="本人">╱</td>';
        const match=event.matches.find(m=>m.phase==='group'&&[m.a_id,m.b_id].includes(row.user_id)&&[m.a_id,m.b_id].includes(col.user_id));
        const own=match&&[match.a_id,match.b_id].includes(state.user?.id);
        if(match?.status==='accepted'&&own){
            return `<td class="matrix-pending"><button class="matrix-record" data-action="matrix-report" data-id="${match.id}" aria-label="录入${esc(row.name)}对${esc(col.name)}的成绩">${icon('plus')}录入</button></td>`;
        }
        if(!match||!['reported','completed'].includes(match.status))return '<td class="matrix-pending">—</td>';
        const left=match.a_id===row.user_id;
        const score=left?[match.score_a,match.score_b]:[match.score_b,match.score_a];
        const result=match.winner_id===row.user_id?'胜':'负';
        const content=`<strong>${score[0]}∶${score[1]}</strong><small>${result}${match.forfeit_reason?' · 弃权':match.status==='reported'?' · 已录入':''}</small>`;
        return `<td class="${result==='胜'?'matrix-win':'matrix-loss'}">${own?`<button class="matrix-score" data-action="matrix-view" data-id="${match.id}" aria-label="查看${esc(row.name)}对${esc(col.name)}的成绩">${content}</button>`:content}</td>`;
    };
    return `<section class="panel event-matrix-panel"><div class="panel-title"><h2>实时比分表</h2></div><p class="hint">点击自己对战的「录入」填写成绩，已有比分可点击查看。比分以行球员为准，横向滑动查看，新成绩录入后自动同步。</p><div class="table-wrap"><table class="event-matrix"><thead><tr><th scope="col">球员 / 对手</th>${players.map(p=>`<th scope="col">${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${players.map(p=>`<tr><th scope="row">${esc(p.name)}${p.absent_reason?'<small>缺席</small>':''}</th>${players.map(q=>cell(p,q)).join('')}</tr>`).join('')}</tbody></table></div></section>`;
}
function editEventResult(mid,eid){
    const match=activeEvent?.matches.find(m=>m.id===mid)||findSingleMatch(mid);
    if(!match)return;
    const games=match.forfeit_reason?[]:JSON.parse(match.games||'[]');
    modal('修改比赛结果',`${esc(match.a_name)}（左） 对 ${esc(match.b_name)}（右） · ${best(match.best_of)}`,`<form data-form="event-result" data-id="${mid}" data-event="${eid}">${Array.from({length:match.best_of},(_,i)=>`<div class="game-input"><label>第${i+1}局</label><input name="a${i}" type="number" min="0" max="199" aria-label="第${i+1}局左方得分" value="${games[i]?.[0]??''}"><span>∶</span><input name="b${i}" type="number" min="0" max="199" aria-label="第${i+1}局右方得分" value="${games[i]?.[1]??''}"></div>`).join('')}${field('修改原因','reason','text','请说明更正原因',true,'minlength="2" maxlength="200"')}<p class="hint">赛果立即更新，个人积分00:00结算或重算。影响晋级时，后续对阵会重新生成，小组赛更正后需重新设置晋级。</p><div class="form-error" role="alert"></div><button class="btn full" type="submit">保存比赛结果</button></form>`);
}
document.addEventListener('click',e=>{
    const button=e.target.closest('[data-action="event-result"]');
    if(button&&state.user?.role==='admin')editEventResult(Number(button.dataset.id),Number(button.dataset.event));
});
document.addEventListener('submit',async e=>{
    const form=e.target.closest('form[data-form="event-result"]');
    if(!form)return;
    e.preventDefault();
    const button=form.querySelector('[type="submit"]');
    button.disabled=true;
    try{
        const data=new FormData(form),games=[];
        let blank=false;
        for(let i=0;i<7;i++){
            const a=data.get('a'+i),b=data.get('b'+i);
            if(a===null)break;
            if(a===''&&b===''){blank=true;continue}
            if(blank||a===''||b==='')throw Error('请按顺序填写每局双方得分');
            games.push([Number(a),Number(b)]);
        }
        await mutation(`events/${form.dataset.event}/result`,{match_id:Number(form.dataset.id),games,reason:data.get('reason')});
    }catch(err){form.querySelector('.form-error').textContent=err.message}finally{button.disabled=false}
});


document.addEventListener('click',async e=>{
    const button=e.target.closest('[data-action="matrix-report"],[data-action="matrix-view"]');
    if(!button||button.disabled)return;
    const match=findSingleMatch(button.dataset.id);
    if(!match||![match.a_id,match.b_id].includes(state.user?.id))return;
    if(button.dataset.action==='matrix-report')return report(match.id,state.user.id);
    modal('比赛成绩',`${esc(match.a_name)} vs ${esc(match.b_name)}`,matchCard(match));
});
